import { useState } from "react";
import { createRoot } from "react-dom/client";

// 처음 보여 줄 할 일이에요. 새 번호는 3부터 이어서 써요.
const initialTodos = [
  { id: 1, text: "우유 사기", done: false },
  { id: 2, text: "빵 사기", done: true },
];
let nextId = 3;

function App() {
  // 입력칸 글자는 상태예요. 입력할 때마다 setText가 새 글자를 알려요.
  const [text, setText] = useState("");
  // 목록 자료예요. 이 줄이 일반 변수인지 상태인지가 이번 문제예요.
  let todos = initialTodos;
  const remaining = todos.filter(todo => !todo.done).length;

  function addFromInput() {
    // 앞뒤 공백을 빼고, 빈 글자는 추가하지 않아요.
    const value = text.trim();
    if (value === "") return;
    const todo = { id: nextId, text: value, done: false };
    nextId += 1;
    todos = [...todos, todo];
    setText("");
  }

  return (
    <main>
      <h1>오늘 할 일</h1>
      <div className="todo-form">
        <label htmlFor="todo-input">새 할 일</label>
        <input id="todo-input" value={text} onChange={e => setText(e.target.value)} />
        <button id="add-button" type="button" onClick={addFromInput}>추가</button>
      </div>
      <ul id="todo-list">
        {todos.map(todo => (
          <li key={todo.id} className={todo.done ? "done" : ""}>
            <span>{todo.text}</span>
          </li>
        ))}
      </ul>
      <p id="todo-count">남은 일 {remaining}개</p>
    </main>
  );
}

// index.html의 root 요소 안에 App이 돌려준 요소를 그려요.
createRoot(document.getElementById("root")).render(<App />);

