import { useState } from "react";
import { createRoot } from "react-dom/client";

// 처음 보여 줄 할 일이에요. 새 번호는 3부터 이어서 써요.
const initialTodos = [
  { id: 1, text: "우유 사기", done: false },
  { id: 2, text: "빵 사기", done: true },
];
let nextId = 3;

// 할 일 하나를 받아 목록의 한 줄을 그려요. App이 todo와 onToggle을 넘겨줘요.
function TodoItem({ todo, onToggle }) {
  return (
    <li className={todo.done ? "done" : ""}>
      <span>{todo.text}</span>
      <button className="toggle" type="button" onClick={() => onToggle(todo.id)}>완료</button>
    </li>
  );
}

function App() {
  // 입력칸 글자는 상태예요. 입력할 때마다 setText가 새 글자를 알려요.
  const [text, setText] = useState("");
  const [todos, setTodos] = useState(initialTodos);
  // 남은 수는 따로 저장하지 않고 todos에서 계산해요.
  const remaining = todos.filter(todo => !todo.done).length;

